#include <iostream>
#include <string>
#include <string_view>

class GradeBook {
public:
    explicit GradeBook(std::string_view name) {
        setCourseName(name);
    }

    void setCourseName(std::string_view name) {
        if (name.size() <= 25) {
            courseName = name;
        } else {
            courseName = name.substr(0, 25);
            std::cerr << "Name \"" << name << "\" exceeds maximum length (25).\n"
                      << "Limiting courseName to first 25 characters.\n";
        }
    }

    std::string getCourseName() const {
        return courseName;
    }

    void displayMessage() const {
        std::cout << "Welcome to the grade book for\n" << getCourseName() << "!\n\n";
    }

    void determineClassAverage() const {
        int total = 0;
        unsigned int gradeCounter = 1;

        while (gradeCounter <= 10) {
            std::cout << "Enter grade: ";
            int grade = 0;
            std::cin >> grade;
            total = total + grade;
            gradeCounter = gradeCounter + 1;
        }

        int average = total / 10;
        std::cout << "\nTotal of all 10 grades is " << total << "\n";
        std::cout << "Class average is " << average << "\n";
    }

private:
    std::string courseName;
};

int main() {
    GradeBook myGradeBook("CS101 C++ Programming");
    myGradeBook.displayMessage();
    myGradeBook.determineClassAverage();
    return 0;
}

#include <iostream>
#include <limits>

int main() {
    int sum = 846;
    int count = 10;
    int counterAfterLoop = 11; // Counter value after finishing loop 1..10

    // 1. Integer division truncation
    int intAverage = sum / count;
    double exactAverage = static_cast<double>(sum) / count;

    std::cout << "Integer division result: " << intAverage << "\n";
    std::cout << "Floating-point result: " << exactAverage << "\n";

    // 2. Off-by-one error demonstration
    int faultyAverage = sum / counterAfterLoop;
    std::cout << "Faulty average using post-loop counter (11): " << faultyAverage << "\n";

    // 3. Overflow demonstration check
    int maxInt = std::numeric_limits<int>::max();
    std::cout << "Max representable signed int: " << maxInt << "\n";

    return 0;
}
